parameters.jsCode:
const topicData = $('Get Pending Topic').first().json;

return $input.all().map(row => {
  for (const key of ['System Prompt', 'User Prompt']) {
    let text = row.json[key] ?? '';
    for (const [k, v] of Object.entries(topicData)) {
      text = text.split(`{{${k}}}`).join(String(v ?? ''));
    }
    row.json[key] = text;
  }
  return row;
});

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "thread": {
      "type": "array",
      "minItems": 5,
      "maxItems": 7,
      "items": {
        "type": "string",
        "pattern": "^[^*]*$"
      },
      "description": "Twitter only: 5 to 7 tweets in order, each under 280 characters and each making a different point. Plain text with no markdown, no asterisks and no numbering."
    },
    "linkedin_post": {
      "type": "string",
      "pattern": "^[^*]*$",
      "description": "LinkedIn only: the complete post as plain text. No markdown and no asterisks. Use blank lines between paragraphs and write the takeaways as lines starting with 1., 2., 3."
    },
    "facebook_post": {
      "type": "string",
      "pattern": "^[^*]*$",
      "description": "Facebook only: one single post as plain text, with a one-line hook, three to five short value lines each on its own line, and a final call to action. No slide labels, no markdown and no asterisks."
    },
    "title": {
      "type": "string",
      "description": "YouTube only: a click-worthy video title that is clearly different from the blog title"
    },
    "hook": {
      "type": "string",
      "description": "YouTube only: the opening hook, under 25 words, that does not promise a video length"
    },
    "outline": {
      "type": "array",
      "description": "YouTube only: timed script sections, starting at 0:00",
      "items": {
        "type": "object",
        "properties": {
          "time": {
            "type": "string",
            "description": "Timestamp estimate, for example 1:20"
          },
          "section": {
            "type": "string",
            "description": "What is covered in this section"
          }
        },
        "required": ["time", "section"]
      }
    },
    "closing_cta": {
      "type": "string",
      "description": "YouTube only: the closing call to action"
    }
  }
}

