parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "seo_title": {
      "type": "string",
      "description": "SEO-optimized blog title with keywords, plain text"
    },
    "meta_description": {
      "type": "string",
      "description": "Meta description of exactly 25 words, which is about 155 characters. One sentence, plain text, never longer than 160 characters."
    },
    "blog_content": {
      "type": "string",
      "description": "The full blog post body as pure HTML (h2, h3, p, ul, li, strong, code), starting with the featured-snippet intro paragraph and ending with an FAQ section. Do not repeat the blog title as a heading. No markdown and no code fences."
    }
  },
  "required": ["seo_title", "meta_description", "blog_content"]
}
